public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null || word1.length() == 0 || word2.length() == 0) {
        return "Invalid input";
    }

    int commonLetters = 0;
    for (int i = 0; i < word1.length(); ++i) {
        for (int j = 0; j < word2.length(); ++j) {
            if (word1.charAt(i) == word2.charAt(j)) {
                ++commonLetters;
                break;
            }
        }
    }

    long numerator = commonLetters;
    long denominator = word1.length() + word2.length();

    // Reduce the fraction
    for (int divisor = 2; divisor <= Math.min(numerator, denominator); ++divisor) {
        if (numerator % divisor == 0 && denominator % divisor == 0) {
            numerator /= divisor;
            denominator /= divisor;
        }
    }

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

