public String sortString(String s) {
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    // Add all characters from the string to their respective heaps
    for (char c : s.toCharArray()) {
        if (c >= '0' && c <= '9') minHeap.offer(c);
        else maxHeap.offer(c);
    }

    StringBuilder result = new StringBuilder();
    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        // Append the smallest character from minHeap
        if (!minHeap.isEmpty()) result.append(minHeap.poll());
        // Append the largest character from maxHeap
        if (!maxHeap.isEmpty()) result.append(maxHeap.poll());
    }

    return result.toString();
}

