        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n + 1];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + Math.min(dp[i - 2], dp[i - 3]);
    }

    return dp[n];
}

