public int maxAbsoluteSum(int[] nums) {
    int n = nums.length;
    if (n == 0) return 0;

    int maxSum = nums[0];
    int minSum = nums[0];

    int result = 0;

    for (int i = 1; i < n; i++) {
        int currentMax = Math.max(nums[i], nums[i] + maxSum);
        int currentMin = Math.min(nums[i], nums[i] + minSum);

        maxSum = currentMax;
        minSum = currentMin;

        result = Math.max(result, Math.abs(maxSum - minSum));
    }

    return result;
}

public int findMinFibonacciNumbers(int k) {
    // Helper array to store Fibonacci numbers up to k
    int[] fib = new int[Math.min(k, 150)];
    fib[0] = 1;
    fib[1] = 1;

    // Generate Fibonacci numbers up to k
    for (int i = 2; i <= Math.min(k, 150); i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    int minCount = Integer.MAX_VALUE;
    // Find all possible combinations using the Fibonacci numbers to reach k
    for (int i = fib.length - 1; i >= 0; i--) {
        int a = 1;
        while (a * fib[i] <= k) {
            a++;
        }
        a--;
        k -= a * fib[i];
        minCount = Math.min(minCount, a + findMinFibonacciNumbers(k));
    }

    return minCount;
}

