public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) return 0;

    int ones = 0, twos = 0;

    for (int num : nums) {
        ones = ones ^ num & ~twos; // XOR with the bitwise NOT of twos to cancel part of nums
        twos = twos ^ num & ones;  // XOR with the bitwise AND of nums and ones to cancel part of ones
    }

    return ones; // The final ones will hold the unique number
}

