    }

    int maxLen = 0;
    int m = mat.length;
    int n = mat[0].length;

    // Calculate lengths of longest lines horizontally
    for (int i = 0; i < m; i++) {
        int cnt = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                cnt++;
            } else {
                cnt = 0;
            }
            maxLen = Math.max(maxLen, cnt);
        }
    }

    // Calculate lengths of longest lines vertically
    for (int j = 0; j < n; j++) {
        int cnt = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                cnt++;
            } else {
                cnt = 0;
            }
            maxLen = Math.max(maxLen, cnt);
        }
    }

    // Calculate lengths of longest lines diagonally
    for (int i = 0, j = 0; i < m && j < n; i++, j++) {
        int cnt = 1;
        while (i + 1 < m && j + 1 < n && mat[i + 1][j + 1] == 1) {
            cnt++;
            i++;
            j++;
        }
        maxLen = Math.max(maxLen, cnt);
    }

    // Calculate lengths of longest lines anti-diagonally
    for (int i = 0, j = n - 1; i < m && j >= 0; i++, j--) {
        int cnt = 1;
        while (i + 1 < m && j - 1 >= 0 && mat[i + 1][j - 1] == 1) {
            cnt++;
            i++;
            j--;
        }
        maxLen = Math.max(maxLen, cnt);
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
