    return result; // Return the string with thousand separators added
}

public static long countSquarePermutations(int[] A) throws IllegalArgumentException {
        if (A == null) {
            throw new IllegalArgumentException("The input array cannot be null");
        }
        return countPermutationsHelper(A, 0, 0, Integer.MAX_VALUE, 0, 0);
    }

    private static long countPermutationsHelper(int[] A, int i, int z, long sumValue, long count, long state) throws IllegalArgumentException {
        int L = A.length - 1 - i;
        if (L <= i) {
            return count;
        }
        if (sumValue >= A[L] || A[i] >= A[L]) {
            return count;
        }
        state |= (1L << (A[i] - 1));
        if (sumValue + A[i] * 2 == (int) Math.sqrt(sumValue + A[i] * 2) * (int) Math.sqrt(sumValue + A[i] * 2)) if ((state & (1L << (z + A[i] - 1))) == 0) {
            long newCount = countPermutationsHelper(A, i + 1, i, i + A[i], count + 1, state);
            count = newCount;
        }
        return countPermutationsHelper(A, i + 1, z, sumValue, count, state);
    }
}

