                row++;
            }
        } else if (direction == 2) {
            if (row == 0) {
                direction = 3;
                col++;
            } else {
                row--;
            }
        } else if (direction == 3) {
            if (col == 0) {
                direction = 0;
                row++;
            } else {
                col--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the input integer to a character array for manipulation
    char[] digits = String.valueOf(n).toCharArray();

    // Find the first digit from the right that is smaller than the digit next to it
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the rightmost digit greater than the current digit
            for (int j = digits.length - 1; j >= i; j--) {
                if (digits[j] > digits[i]) {
                    // Swap the two digits
                    char temp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = temp;
                    // Sort the substring to the right of the swapped digit
                    Arrays.sort(digits, i + 1, digits.length);
                    // Convert the character array back to an integer
                    return Integer.parseInt(new String(digits));
                }
            }
        }
    }
    // If no such pair is found, return -1
    return -1;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerNumbers = new ArrayList<>();
    if (n < 1) return centerNumbers; // No center symmetric numbers for length less than 1

    // Determining the starting point based on the length of the string
    int start = (n + 1) / 2;

    // Building the center symmetric numbers
    for (int i = start, j = Math.abs(start - n); j <= n; i++, j--) {
        StringBuilder centerSymmetric = new StringBuilder();
        for (int k = 0; k < j; k++) {
            if (i == k || i + k == n) {
                centerSymmetric.insert(k, '8'); // Filling symmetric positions with '8'
            } else {
                centerSymmetric.insert(k, '6'); // Filling symmetric positions with '6'
            }
        }
        centerNumbers.add(centerSymmetric.toString());
    }
    return centerNumbers;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the points are in a square shape
    boolean isSquare = points[1][0] == points[2][0] && points[1][1] == points[2][1] || points[0][0] == points[2][0] && points[0][1] == points[2][1] || points[0][0] == points[1][0] && points[0][1] == points[1][1];

    // Calculate the average of the points
    double avgX = (points[0][0] + points[1][0] + points[2][0]) / 3;
    double avgY = (points[0][1] + points[1][1] + points[2][1]) / 3;

    // Calculate the distances from each point to the average
    double dist1 = Math.sqrt(Math.pow(points[0][0] - avgX, 2) + Math.pow(points[0][1] - avgY, 2));
    double dist2 = Math.sqrt(Math.pow(points[1][0] - avgX, 2) + Math.pow(points[1][1] - avgY, 2));
    double dist3 = Math.sqrt(Math.pow(points[2][0] - avgX, 2) + Math.pow(points[2][1] - avgY, 2));

    // A boomerang satisfies the condition that the sum of the distances from each point to the average is not equal to twice the distance from any one point to the average
    return dist1 + dist2 + dist3 != 2 * Math.min(dist1, Math.min(dist2, dist3));
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    int[] dp = new int[n];
    dp[0] = 1;

    int p2 = 0; // Index for the next multiple of 2
    int p3 = 0; // Index for the next multiple of 3
    int p5 = 0; // Index for the next multiple of 5

    for (int i = 1; i < n; i++) {
        int nextMultipleOf2 = dp[p2] * 2;
        int nextMultipleOf3 = dp[p3] * 3;
        int nextMultipleOf5 = dp[p5] * 5;

        int nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        dp[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            p2++;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            p3++;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            p5++;
        }
    }

    return dp[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;
    char lastChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == lastChar) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
        lastChar = s.charAt(i);
    }

    return Math.max(maxEnergy, currentEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result; // Handle edge cases

    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current); // Add the current number to the result list
        int next = 10 * current + 1; // Calculate the next number in lexicographical order
        while (next <= n) {
            result.add(next); // Add all possible next numbers to the result list
            current = next;
            next = 10 * current + 1;
        }
        current = 1; // Move back to the first digit
    }

    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    // Add each number to the set
    for (int num : nums) {
        uniqueElements.add(num);
    }
    // Calculate and return the sum of the unique elements
    return uniqueElements.stream().mapToInt(Integer::intValue).sum();
}

public static int minPerfectSquareSum(int n) {
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0; // Base case: 0 perfect squares need 0 squared numbers

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                int square = j * j;
                if (square <= i) {
                    dp[i] = Math.min(dp[i], dp[i - square] + 1);
                }
            }
        }
        return dp[n];
    }

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Split the string into words
    String[] words = s.split("\\s+");

    // Reverse each word and join them with spaces
    StringBuilder reversedSentence = new StringBuilder();
    for (String word : words) {
        int i = 0;
        int j = word.length() - 1;
        while (i < j) {
            char temp = word.charAt(i);
            word.setCharAt(i, word.charAt(j));
            word.setCharAt(j, temp);
            i++;
            j--;
        }
        reversedSentence.append(word).append(" ");
    }

    // Remove the trailing space
    return reversedSentence.toString().trim();
}
